#include <iostream>

int main() {
    constexpr unsigned int SIZE = 5;
    unsigned int values[SIZE] = {2, 4, 6, 8, 10};
    unsigned int* vPtr = values;

    // 1. Array subscript
    for (size_t i = 0; i < SIZE; ++i) {
        std::cout << values[i] << (i + 1 == SIZE ? "\n" : " ");
    }

    // 2. Pointer/offset with pointer variable
    for (size_t j = 0; j < SIZE; ++j) {
        std::cout << *(vPtr + j) << (j + 1 == SIZE ? "\n" : " ");
    }

    // 3. Pointer/offset with array name
    for (size_t k = 0; k < SIZE; ++k) {
        std::cout << *(values + k) << (k + 1 == SIZE ? "\n" : " ");
    }

    // 4. Pointer subscript
    for (size_t m = 0; m < SIZE; ++m) {
        std::cout << vPtr[m] << (m + 1 == SIZE ? "\n" : " ");
    }

    // Refer to element 4 (the 5th element) in 4 ways:
    std::cout << values[4] << " " 
              << *(values + 4) << " " 
              << vPtr[4] << " " 
              << *(vPtr + 4) << "\n";

    return 0;
}

